                            setGameProgress(prev => ({
                              ...prev,
                              [game.id]: { completed: true, score: Math.floor(Math.random() * 40 + 60) }
                            }));
                            // Check if at least one game is completed
                            setTimeout(() => {
                              if (Object.keys(gameProgress).length > 0) {
                                setStep5Completed(true);
                              }
                            }, 500);
                          }}
                          disabled={false}
                        >
                          {isCompleted ? "✓ Play Again" : "Play Game"}
                        </button>
                      </div>
                    );
                  })}
                </div>

                {Object.keys(gameProgress).length > 0 && (
                  <div className="games-completion-notice">
                    <h3>🎉 Great Work!</h3>
                    <p>You've completed {Object.values(gameProgress).filter(g => g.completed).length} game(s)! You can now complete the lesson.</p>
                    <button 
                      className="finish-lesson-btn"
                      onClick={() => {
                        setActiveStep(6);
                        alert("Lesson completed! You've earned XP and rewards!");
                      }}
                    >
                      Finish Lesson →
                    </button>
                  </div>
                )}
              </div>
            </section>
          )}
        </div>
      </main>
    </div>
  );
}
